34	use anyhow::anyhow;
35	pub(crate) use config::probe_config_json;
36	use pegainfer_frontend::engine::Engine;
37	use pegainfer_frontend::engine::EngineLoadOptions;
38	use pegainfer_frontend::engine::EpBackend;
39	pub use scheduler::DEFAULT_MAX_PREFILL_TOKENS;
40	
41	/// Maximum supported Qwen3.5 decode scheduler slots.
42	const MAX_DECODE_BATCH: usize = batch_decode_graph::MAX_BATCH;
43	
44	/// Current safe Qwen3.5 Shared-SM overlap admission cap.
45	///
46	/// Decode buckets above this value fall back to the prefill cuBLAS handle today.
47	/// Replaying decode while async prefill concurrently calls that same handle from
48	/// another stream relies on undocumented single-handle multi-stream behavior.
49	/// Keep overlap opt-in below this boundary until the larger decode buckets have
50	/// an independent per-stream handle/workspace route.
51	pub const MAX_SHARED_SM_DECODE_BATCH: usize = ops::GEMM_LT_MAX_N;
52	const _: () = assert!(MAX_SHARED_SM_DECODE_BATCH <= ops::GEMM_LT_MAX_N);
53	
54	/// Low-level Qwen3.5 execution interface.
55	///
56	/// This is for model-local tests, debugging, and benchmarks. The root server
57	/// should use `start_engine` instead.
58	pub mod runtime {
59	    pub use crate::executor::DecodePlan;
60	    pub use crate::executor::DecodeRequestResult;
