121	#[derive(Clone, Debug)]
122	pub struct Qwen35LaunchOptions {
123	    /// CUDA device for single-GPU loads (ignored when `tp_size > 1`).
124	    device_ordinal: usize,
125	    /// Tensor-parallel world size; `> 1` uses devices `0..tp_size`.
126	    tp_size: usize,
127	    /// TP decode captures CUDA Graphs when the rank-local decode GQA group has
128	    /// a compiled kernel; uncompiled groups stay on the eager path.
129	    cuda_graph: bool,
130	    max_batch: usize,
131	    max_prefill_tokens: usize,
132	    prefix_cache_mib: usize,
133	}
134	
135	impl Qwen35LaunchOptions {
136	    /// Configure the runtime and optional per-rank snapshot budget.
137	    pub fn new(
138	        device_ordinal: usize,
139	        tp_size: usize,
140	        cuda_graph: bool,
141	        max_batch: usize,
142	        max_prefill_tokens: usize,
143	        prefix_cache_mib: usize,
144	    ) -> Self {
145	        Self {
146	            device_ordinal,
147	            tp_size,
148	            cuda_graph,
149	            max_batch,
150	            max_prefill_tokens,
151	            prefix_cache_mib,
152	        }
153	    }
154	
155	    fn device_ordinals(&self) -> Result<Vec<usize>> {
156	        anyhow::ensure!(self.tp_size >= 1, "Qwen3.5 tp_size must be >= 1");
157	        Ok(if self.tp_size == 1 {
158	            vec![self.device_ordinal]
159	        } else {
160	            (0..self.tp_size).collect()
161	        })
162	    }
163	}
