165	#[allow(clippy::needless_pass_by_value)]
166	pub fn launch_with_options_policy_and_overlap(
167	    model_path: &Path,
168	    options: Qwen35LaunchOptions,
169	    scheduler_policy: Qwen35SchedulerPolicy,
170	    decode_overlap: Qwen35DecodeOverlap,
171	) -> Result<Engine> {
172	    let device_ordinals = options.device_ordinals()?;
173	    start_engine_with_capacity_policy_and_overlap(
174	        model_path,
175	        EngineLoadOptions {
176	            enable_cuda_graph: options.cuda_graph,
177	            device_ordinals,
178	            parallel_config: None,
179	            ep_backend: EpBackend::Nccl,
180	            seed: 42,
181	        },
182	        options.max_batch,
183	        options.max_prefill_tokens,
184	        scheduler_policy,
185	        decode_overlap,
186	        options.prefix_cache_mib,
187	    )
188	}
189	
190	pub fn start_engine_with_capacity(
191	    model_path: &Path,
192	    options: EngineLoadOptions,
193	    max_batch: usize,
194	    max_prefill_tokens: usize,
195	) -> Result<Engine> {
196	    start_engine_with_capacity_and_policy(
197	        model_path,
198	        options,
199	        max_batch,
200	        max_prefill_tokens,
201	        Qwen35SchedulerPolicy::Off,
202	        0,
203	    )
204	}
205	
206	pub(crate) fn start_engine_with_capacity_and_policy(
207	    model_path: &Path,
208	    options: EngineLoadOptions,
209	    max_batch: usize,
210	    max_prefill_tokens: usize,
211	    scheduler_policy: Qwen35SchedulerPolicy,
212	    prefix_cache_mib: usize,
213	) -> Result<Engine> {
214	    start_engine_with_capacity_policy_and_overlap(
215	        model_path,
216	        options,
217	        max_batch,
218	        max_prefill_tokens,
219	        scheduler_policy,
220	        Qwen35DecodeOverlap::Off,
221	        prefix_cache_mib,
222	    )
223	}
224	
225	pub fn start_engine_with_capacity_policy_and_overlap(
226	    model_path: &Path,
227	    options: EngineLoadOptions,
228	    max_batch: usize,
229	    max_prefill_tokens: usize,
230	    scheduler_policy: Qwen35SchedulerPolicy,
231	    decode_overlap: Qwen35DecodeOverlap,
232	    prefix_cache_mib: usize,
233	) -> Result<Engine> {
234	    anyhow::ensure!(
235	        (1..=MAX_DECODE_BATCH).contains(&max_batch),
236	        "Qwen3.5 max_batch must be in 1..={MAX_DECODE_BATCH}, got {max_batch}"
237	    );
238	    let EngineLoadOptions {
239	        enable_cuda_graph,
240	        device_ordinals,
241	        seed,
242	        ..
243	    } = options;
244	    if decode_overlap == Qwen35DecodeOverlap::SharedSm {
245	        anyhow::ensure!(
246	            max_batch <= MAX_SHARED_SM_DECODE_BATCH,
247	            "Qwen3.5 --decode-overlap=stream currently requires --max-batch <= {MAX_SHARED_SM_DECODE_BATCH}; larger decode buckets still fall back to the prefill GEMM handle"
248	        );
249	    }
250	    let prefix_snapshot_bytes = prefix_cache_mib
251	        .checked_mul(1024 * 1024)
252	        .ok_or_else(|| anyhow!("Qwen3.5 prefix-cache MiB budget overflows usize"))?;
253	    if device_ordinals.len() > 1 {
254	        anyhow::ensure!(
255	            decode_overlap == Qwen35DecodeOverlap::Off,
256	            "Qwen3.5 decode overlap is supported on a single GPU only"
257	        );
258	        if scheduler_policy == Qwen35SchedulerPolicy::Auto {
259	            return Err(anyhow!(
260	                "Qwen3.5 TP uses the fixed off scheduler policy; --qwen35-scheduler-policy=auto is single-GPU only"
261	            ));
262	        }
263	        let model_path = model_path
264	            .to_str()
265	            .ok_or_else(|| anyhow!("model path must be valid UTF-8"))?;
266	        return scheduler::start_tp_with_capacity(
267	            model_path,
268	            seed,
269	            &device_ordinals,
270	            max_batch,
271	            max_prefill_tokens,
272	            enable_cuda_graph,
273	            prefix_snapshot_bytes,
274	        );
275	    }
276	
277	    anyhow::ensure!(
278	        enable_cuda_graph,
279	        "Qwen3.5 decode always captures CUDA Graphs; --cuda-graph=false is not supported"
280	    );
281	    let device_ordinal = match device_ordinals.as_slice() {
282	        [] => 0,
283	        [device_ordinal] => *device_ordinal,
284	        ordinals => {
285	            return Err(anyhow!(
286	                "Qwen3.5 engine supports exactly one CUDA device, got {}",
287	                ordinals.len()
288	            ));
289	        }
290	    };
291	    let model_path = model_path
292	        .to_str()
293	        .ok_or_else(|| anyhow!("model path must be valid UTF-8"))?;
294	    let model = weights::Qwen35Model::from_safetensors(
295	        model_path,
296	        device_ordinal,
297	        max_batch,
298	        prefix_snapshot_bytes,
299	    )?;
300	    scheduler::start_with_capacity_and_policy(
301	        model,
302	        seed,
303	        max_batch,
304	        max_prefill_tokens,
305	        scheduler_policy,
306	        decode_overlap,
307	    )
308	}
